import { supabase } from './supabase';

type Todo = {
  id: string;
  body: string;
  done: boolean;
};

function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : String(error);
}

export default function App() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [newTodo, setNewTodo] = useState('');
  const [signedIn, setSignedIn] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);
  const [todos, setTodos] = useState<Todo[]>([]);
  const [error, setError] = useState('');

  async function loadTodos(forUserId: string) {
    const { data, error: queryError } = await supabase
      .from('todos')
      .select('id, body, done')
      .eq('user_id', forUserId);

    if (queryError) throw queryError;
    setTodos((data ?? []) as Todo[]);
  }

  async function handleSignIn(event: React.FormEvent) {
    event.preventDefault();
    setError('');

    try {
      const { data, error: signInError } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (signInError) throw signInError;
      if (!data.user) throw new Error('Sign-in did not return a user.');

      await loadTodos(data.user.id);
      setUserId(data.user.id);
      setSignedIn(true);
    } catch (caughtError) {
      setError(errorMessage(caughtError));
    }
  }

  async function handleAddTodo(event: React.FormEvent) {
    event.preventDefault();
    setError('');

    try {
      if (!userId) throw new Error('Sign in before adding a todo.');
      const body = newTodo.trim();
      if (!body) return;

      // user_id is deliberately omitted: the database supplies auth.uid().
      const { error: insertError } = await supabase.from('todos').insert({ body });
      if (insertError) throw insertError;

      setNewTodo('');
      await loadTodos(userId);
    } catch (caughtError) {
      setError(errorMessage(caughtError));
    }
  }

  async function handleToggleTodo(todo: Todo) {
    setError('');

    try {
      if (!userId) throw new Error('Sign in before updating a todo.');
      const { error: updateError } = await supabase
        .from('todos')
        .update({ done: !todo.done })
        .eq('id', todo.id);
      if (updateError) throw updateError;

      await loadTodos(userId);
    } catch (caughtError) {
      setError(errorMessage(caughtError));
    }
  }

  return (
    <main>
      <h1>Todos</h1>

      <form onSubmit={handleSignIn}>
        <input
          data-testid="email-input"
          placeholder="Email"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />
        <input
          data-testid="password-input"
          placeholder="Password"
          type="password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
        />
        <button data-testid="sign-in-button" type="submit">
          Sign in
        </button>
      </form>

      {signedIn ? <p data-testid="signed-in">Signed in</p> : null}
      {error ? <p role="alert">{error}</p> : null}

      <form onSubmit={handleAddTodo}>
        <input
          data-testid="todo-input"
          placeholder="New todo"
          value={newTodo}
          onChange={(event) => setNewTodo(event.target.value)}
        />
        <button data-testid="add-button" type="submit">
          Add
        </button>
      </form>

      <ul data-testid="todo-list">
        {todos.map((todo) => (
          <li key={todo.id}>
            <label>
              <input
                data-testid={`todo-checkbox-${todo.body}`}
                type="checkbox"
                checked={todo.done}
                onChange={() => void handleToggleTodo(todo)}
              />
              {todo.body}
            </label>
          </li>
        ))}
      </ul>
    </main>
  );
}
"
}

